/**
 * Shared SVG gradients for the 3D-style icons (order flow, sport tiles)
 * and the sport icons themselves. lukasports_icon_defs() prints the hidden
 * <defs> svg once per page; icons reference its gradients (#skg-*).
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

function lukasports_icon_defs() {
	static $printed = false;
	if ( $printed ) {
		return;
	}
	$printed = true;
	echo '<svg width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false"><defs><linearGradient id="skg-red" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ff6a70"/><stop offset=".45" stop-color="#e01a23"/><stop offset="1" stop-color="#920d13"/></linearGradient><linearGradient id="skg-red-d" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c7131b"/><stop offset="1" stop-color="#6b080c"/></linearGradient><linearGradient id="skg-dark" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#5a6477"/><stop offset=".5" stop-color="#2c3340"/><stop offset="1" stop-color="#12161e"/></linearGradient><linearGradient id="skg-dark-d" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1f2530"/><stop offset="1" stop-color="#090b10"/></linearGradient><linearGradient id="skg-light" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffffff"/><stop offset=".6" stop-color="#e3e7ee"/><stop offset="1" stop-color="#b4bcc9"/></linearGradient><linearGradient id="skg-glass" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#e9f4ff"/><stop offset="1" stop-color="#8fb4d6"/></linearGradient><linearGradient id="skg-shine" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".7"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient><linearGradient id="skg-box-l" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#d4d9e2"/><stop offset="1" stop-color="#a0a9b9"/></linearGradient><linearGradient id="skg-box-r" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b3bac7"/><stop offset="1" stop-color="#7f8999"/></linearGradient><linearGradient id="skg-gold" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffe27a"/><stop offset="1" stop-color="#e8a800"/></linearGradient><linearGradient id="skg-sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#7fd4ff"/><stop offset="1" stop-color="#1f8fd6"/></linearGradient><radialGradient id="skg-orange" cx=".35" cy=".3" r=".9"><stop offset="0" stop-color="#ffb457"/><stop offset=".55" stop-color="#ec6a12"/><stop offset="1" stop-color="#8f3a00"/></radialGradient><radialGradient id="skg-ball" cx=".35" cy=".3" r=".9"><stop offset="0" stop-color="#ffffff"/><stop offset=".6" stop-color="#e6eaf0"/><stop offset="1" stop-color="#a9b2c0"/></radialGradient><radialGradient id="skg-yellow" cx=".35" cy=".3" r=".9"><stop offset="0" stop-color="#fff3a8"/><stop offset=".55" stop-color="#f2c418"/><stop offset="1" stop-color="#b98700"/></radialGradient><radialGradient id="skg-volley" cx=".35" cy=".3" r=".9"><stop offset="0" stop-color="#ffe98a"/><stop offset=".6" stop-color="#f0b90f"/><stop offset="1" stop-color="#a87800"/></radialGradient></defs></svg>'; // phpcs:ignore WordPress.Security.EscapeOutput -- static markup
}

